sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var dueDate = current.due_date;
    var stockConnectTrade = ''; // trade task
    var stock_connect = ''; // trade task template
    var stockConnectTaskTemplate = '';
    var stockConnectTaskTemplate1 = '';
    var due_Date = '';
    var hkgDate = '';
    var todaySeven = '';
    var currDate = '';
    var gdtDate = '';
    var tmrwAtSeven = '';
    var gdr = '';
    var gdtFuture = '';
    var tomDate = '';
    var gdt = '';
    var seconds = '';
    var gdt2 = '';
    var gdtNew = '';
    var tmrwAtThree = '';
    if (current.short_description == 'Create and track a COAST Ticket') {
        gdtNew = new GlideDateTime();
        gdtNew.addDaysUTC(1);
        tmrwAtThree = gdtNew.toString().slice(0, 10) + " 02:00:00";
        current.due_date = tmrwAtThree;
        current.update();
		//current.setWorkflow(false);
    } else {
        var stocktype = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        stocktype.addQuery("number", current.parent.number);
        stocktype.query();
        if (stocktype.next()) {
            stockConnectTrade = stocktype.stock_connect_trade;
            if (stockConnectTrade == "Yes") {
                stockConnectTaskTemplate = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task_template");
                stockConnectTaskTemplate.addQuery("short_description", current.short_description);
                stockConnectTaskTemplate.addQuery('active', 'true');
                stockConnectTaskTemplate.query();
                if (stockConnectTaskTemplate.next()) {

                    stock_connect = stockConnectTaskTemplate.sla_for_stock_connect;
                }
            } else if (stockConnectTrade == "No") {
                stockConnectTaskTemplate1 = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task_template");
                stockConnectTaskTemplate1.addQuery("short_description", current.short_description);
                stockConnectTaskTemplate1.addQuery('active', 'true');
                stockConnectTaskTemplate1.query();
                if (stockConnectTaskTemplate1.next()) {

                    if (stockConnectTaskTemplate1.sla_exception == false) {

                        stock_connect = stockConnectTaskTemplate1.sla_for_non_stock_connect;
                    } else {
                        due_Date = new GlideDateTime(current.due_date);
                        hkgDate = new GlideDateTime();
                        todaySeven = hkgDate.toString().slice(0, 10) + " 10:50:00";
                        currDate = new GlideDateTime(todaySeven);
                        if (currDate.compareTo(due_Date) >= 0) { // due date is smaller than curr date
                            gdtDate = new GlideDateTime();
                            tmrwAtSeven = gdtDate.toString().slice(0, 10) + " 11:00:00";
                            gdr = new GlideDateTime(tmrwAtSeven);
                            current.due_date = gdr;
                        } else {
                            gdtFuture = new GlideDateTime();
                            tomDate = gdtFuture.addDaysUTC(1);
                            current.due_date = tomDate;
                        }
                    }
                }
            }
            gdt = new GlideDateTime(current.due_date);
seconds = stock_connect * 60000;
gdt.add(seconds);
gdt2 = new GlideDateTime(gdt);
current.due_date = gdt2;

current.update();
//current.setWorkflow(false);
        }

    }
})(current, previous);
